$safePackage=function(string$name)use($dir,$uploadDir):string{$name=basename($name);if(!preg_match('/^[A-Za-z0-9_.-]+\.zip$/i',$name))throw new RuntimeException('نام بسته نامعتبر است.');foreach([$dir,$uploadDir]as$base){$p=$base.'/'.$name;if(is_file($p)&&realpath(dirname($p))===realpath($base))return$p;}throw new RuntimeException('بسته در updates یا Upload پیدا نشد.');};
if(($_SERVER['REQUEST_METHOD']??'')==='POST'){$act=(string)($_POST['action']??'');try{if($act==='save_source'){$githubInput=trim((string)($_POST['github_url']??''));$githubInput=preg_replace('#^https?://github\.com/#i','',$githubInput);$githubInput=preg_replace('#/releases.*$#i','',$githubInput);$githubInput=trim($githubInput,'/');if(!preg_match('#^[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+$#',$githubInput))throw new RuntimeException('لینک GitHub باید مانند https://github.com/owner/repository باشد.');RedFoxUpdateSources::save($pdo,$githubInput,'*.zip',false,true);$source=RedFoxUpdateSources::settings($pdo);$allowUnsigned=!empty($source['allow_unsigned_local']);$flash='تنظیمات منبع بروزرسانی ذخیره شد.';}elseif($act==='check_github'){$githubLatest=RedFoxUpdateSources::checkGitHub($pdo);$flash=version_compare($githubLatest['version'],$current,'>')?'نسخه جدید '.$githubLatest['version'].' موجود است.':'نسخه جدیدتری پیدا نشد.';}elseif($act==='download_github'){$meta=RedFoxUpdateSources::checkGitHub($pdo);if(!version_compare($meta['version'],$current,'>'))throw new RuntimeException('نسخه GitHub جدیدتر نیست.');$target=$dir.'/github-'.preg_replace('/[^A-Za-z0-9._-]/','_',$meta['version']).'-'.bin2hex(random_bytes(3)).'.zip';RedFoxUpdateSources::download($meta['url'],$target);$info=RedFoxSecureUpdater::inspect($target,$current);$flash='بسته GitHub دانلود و امضای Ed25519 آن تأیید شد: '.$info['version'];}elseif($act==='upload'){if(!isset($_FILES['package'])||$_FILES['package']['error']!==UPLOAD_ERR_OK)throw new RuntimeException('آپلود ناموفق بود.');$tmp=$_FILES['package']['tmp_name'];$name=(string)$_FILES['package']['name'];$size=(int)$_FILES['package']['size'];if(!is_uploaded_file($tmp)||$size<100||$size>134217728||strtolower(pathinfo($name,PATHINFO_EXTENSION))!=='zip')throw new RuntimeException('ZIP یا اندازه نامعتبر است.');$target=$dir.'/upload-'.date('YmdHis').'-'.bin2hex(random_bytes(3)).'.zip';if(!move_uploaded_file($tmp,$target))throw new RuntimeException('ذخیره آپلود ناموفق بود.');chmod($target,0600);$info=RedFoxSecureUpdater::inspect($target,$current);$pdo->prepare("UPDATE update_sources SET last_check_at=?,last_version=?,last_source='upload',last_file=?,last_error=NULL WHERE id=1")->execute([time(),$info['version'],$target]);$flash='بسته امضاشده شناسایی شد: '.$info['version'];}elseif($act==='install_ajax'){$path=$safePackage((string)($_POST['file']??''));$svc=new RedFoxInPlaceUpdater($pdo,$root);$preview=$svc->plan($path,false);$jobId=(string)($_POST['job_id']??'');if(!preg_match('/^[a-f0-9]{32}$/',$jobId))throw new RuntimeException('Job ID نامعتبر است.');$backupChoice=(string)($_POST['backup_choice']??'');if($backupChoice!=='create')throw new RuntimeException('بکاپ دیتابیس و Rollback برای بروزرسانی اجباری است.');session_write_close();$result=$svc->install($path,(string)($_POST['source']??'local'),(string)$admin['username'],false,$jobId,true);$archive=$dir.'/archive/'.basename($path,'.zip').'-installed-'.date('YmdHis').'.zip';@rename($path,$archive);$current=$result['version'];$flash='✅ بروزرسانی کامل شد؛ نسخه '.$result['version'].' — تغییر: '.$result['changed'].'، جدید: '.$result['added'].'، حفظ‌شده: '.$result['skipped'];rx_log_event_structured('info','update.completed',$result);header('Content-Type:application/json; charset=utf-8');echo json_encode(['ok'=>true,'result'=>$result,'message'=>$flash],JSON_UNESCAPED_UNICODE);exit;}elseif($act==='delete'){$path=$safePackage((string)($_POST['file']??''));unlink($path);$flash='بسته حذف شد.';}}catch(Throwable$e){if(isset($target)&&is_file($target))@unlink($target);$msg=redfox_public_exception($e, 'panel/update.php');$flash=$msg;$ft='error';rx_log_event_structured('error','update.failed',['error'=>redfox_exception_fingerprint($e),'action'=>$act]);if($act==='install_ajax'){header('Content-Type:application/json; charset=utf-8');http_response_code(500);echo json_encode(['ok'=>false,'error'=>$msg],JSON_UNESCAPED_UNICODE);exit;}}}
