?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>مرکز بروزرسانی</title><link rel="stylesheet" href="css/theme.css"><style>.update-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:14px}.source-card{position:relative;border:1px solid var(--border-soft);border-radius:18px;padding:20px;background:linear-gradient(145deg,var(--surface-2),var(--surface-1));box-shadow:0 12px 34px rgba(0,0,0,.2);transition:transform .2s,border-color .2s}.source-card:hover{transform:translateY(-3px);border-color:var(--accent-mid)}.source-card h2{margin-bottom:12px;font-size:17px}.source-card p{color:var(--text-muted);line-height:1.9;margin-top:10px}.good{color:var(--color-success)}.bad{color:var(--color-danger)}.warn{color:#f59e0b}.progress-overlay{display:none;position:fixed;inset:0;background:rgba(0,0,0,.82);z-index:9999;align-items:center;justify-content:center;text-align:center;color:#fff}.progress-overlay.show{display:flex}.spinner{width:54px;height:54px;border:5px solid #374151;border-top-color:var(--accent);border-radius:50%;animation:spin 1s linear infinite;margin:auto}@keyframes spin{to{transform:rotate(360deg)}}.progress-panel{width:min(620px,92vw);padding:28px;background:linear-gradient(145deg,#151925,#0d1018);border:1px solid rgba(255,255,255,.14);border-radius:22px;box-shadow:0 30px 90px rgba(0,0,0,.6)}.update-progress-track{height:18px;background:#242938;border-radius:99px;overflow:hidden;margin:20px 0 10px;box-shadow:inset 0 2px 6px rgba(0,0,0,.5)}.update-progress-bar{height:100%;border-radius:99px;background:linear-gradient(90deg,#2563eb,#22c55e,#06b6d4);background-size:200% 100%;transition:width .45s ease;animation:flow 2s linear infinite}.update-progress-meta{display:flex;justify-content:space-between;color:#cbd5e1}.update-progress-meta b{font-size:22px;color:#fff}.progress-help{font-size:12px;color:#94a3b8;margin-top:16px;line-height:2}.progress-result{display:none;margin-top:14px;padding:12px;border-radius:10px}.progress-result.ok{display:block;background:rgba(34,197,94,.15);color:#86efac}.progress-result.fail{display:block;background:rgba(239,68,68,.15);color:#fca5a5}.backup-choice-overlay{display:none;position:fixed;inset:0;background:rgba(2,6,12,.84);backdrop-filter:blur(9px);z-index:9998;align-items:center;justify-content:center}.backup-choice-overlay.show{display:flex}.backup-choice-panel{width:min(610px,92vw);padding:28px;border:1px solid rgba(255,255,255,.14);border-radius:22px;background:linear-gradient(145deg,#171b28,#0d111a);box-shadow:0 30px 90px rgba(0,0,0,.65);text-align:center}.backup-choice-icon{font-size:46px}.backup-choice-actions{display:flex;gap:12px;justify-content:center;flex-wrap:wrap;margin-top:22px}.backup-choice-note{padding:12px;border-radius:12px;background:rgba(245,158,11,.10);color:#fcd34d;line-height:1.9;margin-top:14px}@keyframes flow{to{background-position:200% 0}}code{font-size:11px}</style></head><body><div id="backupChoice" class="backup-choice-overlay"><div class="backup-choice-panel"><div class="backup-choice-icon">🛡️</div><h2>پیش از نصب، بکاپ گرفته شود؟</h2><p>پیشنهاد می‌شود قبل از بروزرسانی یک بکاپ رمزنگاری‌شده از دیتابیس ساخته شود. در صورت انتخاب بکاپ، فایل داخل پوشه بکاپ همان بروزرسانی ذخیره می‌شود.</p><div class="backup-choice-note">بکاپ رمزنگاری‌شده دیتابیس و امکان Rollback پیش‌نیاز اجباری نصب است.</div><div class="backup-choice-actions"><button type="button" id="createBackupBtn" class="btn btn-success">✅ بکاپ بگیر و ادامه بده</button><button type="button" id="cancelUpdateBtn" class="btn btn-danger">انصراف</button></div></div></div><div id="updateProgress" class="progress-overlay"><div class="progress-panel"><div class="spinner"></div><h2 id="progressTitle">آماده‌سازی بروزرسانی</h2><p id="progressStage">در حال ایجاد Job امن...</p><div class="update-progress-track"><div id="progressBar" class="update-progress-bar" style="width:0%"></div></div><div class="update-progress-meta"><b id="progressPercent">0٪</b><span id="progressFiles">0 / 0 فایل</span></div><div id="progressResult" class="progress-result"></div><p class="progress-help">در صورت انتخاب شما بکاپ دیتابیس ساخته می‌شود؛ سپس فایل‌های تغییرکرده جایگزین و Migrationها اجرا می‌شوند.</p></div></div><section id="container"><?php include'header.php';?><section id="main-content"><div class="wrapper"><div class="page-head"><h1 class="page-head__title">مرکز بروزرسانی ساده و امن</h1><div class="page-head__sub">نسخه فعلی <?=htmlspecialchars($current)?> — فایل کامل پروژه، پوشه سرور یا انتشار GitHub</div></div><?php if($flash):?><div class="card <?=$ft==='error'?'bad':'good'?>"><?=htmlspecialchars($flash)?></div><?php endif;?><?php if($githubLatest&&version_compare((string)$githubLatest['version'],$current,'>')):?><div class="card good"><h2>🎉 نسخه <?=htmlspecialchars($githubLatest['version'])?> موجود است</h2><form method="post"><input type="hidden" name="action" value="download_github"><button class="btn btn-success">دانلود از GitHub و آماده‌سازی</button></form></div><?php endif;?><?php if($bestPackage):?><div class="card good"><h2>🚀 نسخه جدید <?=htmlspecialchars($bestPackage['version'])?> در دسترس است</h2><p>منبع شناسایی‌شده: پوشه <?=htmlspecialchars($bestPackage['folder'])?> — بسته آماده نصب است.</p><form method="post" class="install-form"><input type="hidden" name="action" value="install_ajax"><input type="hidden" name="job_id" value="<?=bin2hex(random_bytes(16))?>"><input type="hidden" name="file" value="<?=htmlspecialchars($bestPackage['file'])?>"><input type="hidden" name="source" value="<?=htmlspecialchars(strtolower((string)$bestPackage['folder'])==='upload'?'upload-folder':'updates-folder')?>"><input type="hidden" name="backup_choice" value=""><button class="btn btn-success install-update-btn" data-version="<?=htmlspecialchars($bestPackage['version'],ENT_QUOTES)?>" data-signed="1">⬆️ نصب نسخه جدید</button></form></div><?php endif;?><div class="page-guide">💡 فایل نسخه جدید را از Upload، پوشه سرور یا GitHub آماده کنید و فقط روی «نصب بروزرسانی» بزنید. بررسی نسخه و فایل‌های تغییرکرده خودکار است. بکاپ رمزنگاری‌شده دیتابیس و بکاپ فایل‌ها پیش از نصب اجباری است و در صورت خطا Rollback انجام می‌شود.</div><div class="update-grid"><div class="source-card"><h2>📦 بارگذاری فایل کامل پروژه</h2><form method="post" enctype="multipart/form-data"><input type="hidden" name="action" value="upload"><input type="file" name="package" accept=".zip" required><button class="btn btn-primary">آپلود و بررسی</button></form><p>فقط بسته دارای manifest و امضای معتبر Ed25519 پذیرفته می‌شود.</p></div><div class="source-card"><h2>🌐 بررسی مسیر GitHub</h2><form method="post"><input type="hidden" name="action" value="check_github"><button class="btn btn-primary">بررسی نسخه جدید</button></form><p><?=htmlspecialchars((string)($source['github_repo']??'مخزن تنظیم نشده'))?></p></div><div class="source-card"><h2>📁 بسته‌های موجود روی هاست</h2><p>هر ZIP داخل <code><?=htmlspecialchars($dir)?></code> یا <code><?=htmlspecialchars($uploadDir)?></code> خودکار بررسی و در جدول پایین نمایش داده می‌شود.</p></div></div><div class="card"><h2>🌐 مسیر دریافت بروزرسانی از GitHub</h2><p class="page-guide">مسیر مخزن را به‌شکل owner/repository وارد و ذخیره کنید؛ نمونه: myname/redfox. بررسی نسخه از Releaseهای همان مخزن انجام می‌شود.</p><form method="post"><input type="hidden" name="action" value="save_source"><label style="display:block;margin-bottom:6px">لینک کامل پروژه در GitHub</label><input type="url" name="github_url" value="<?=htmlspecialchars(!empty($source['github_repo'])?'https://github.com/'.(string)$source['github_repo']:'')?>" placeholder="https://github.com/owner/repository" required style="width:min(620px,100%);direction:ltr"><button class="btn btn-primary">ذخیره لینک GitHub</button></form><p class="page-guide">پس از ذخیره، دکمه «بررسی نسخه جدید» از همین مخزن Releaseها را بررسی می‌کند. فایل کامل محلی نیز مستقل از GitHub قابل نصب است.</p></div><div class="card"><h2>بسته‌های آماده نصب</h2><div class="table-wrap"><table class="app-table"><tr><th>فایل</th><th>نسخه/نوع</th><th>حجم</th><th>عملیات</th></tr><?php foreach($packages as$p):?><tr><td><b><?=htmlspecialchars($p['file'])?></b><br><small>پوشه: <?=htmlspecialchars($p['folder'])?></small></td><td><?php if($p['valid']):?><?=htmlspecialchars($p['version'])?> — <span class="good">امضاشده Ed25519</span><?php else:?><span class="bad"><?=htmlspecialchars($p['error'])?></span><?php endif;?></td><td><?=number_format((int)$p['size'])?></td><td><?php if($p['valid']):?><form method="post" class="install-form" style="display:inline"><input type="hidden" name="action" value="install_ajax"><input type="hidden" name="job_id" value="<?=bin2hex(random_bytes(16))?>"><input type="hidden" name="file" value="<?=htmlspecialchars($p['file'])?>"><input type="hidden" name="source" value="<?=htmlspecialchars(strtolower((string)$p['folder'])==='upload'?'upload-folder':'updates-folder')?>"><input type="hidden" name="backup_choice" value=""><button class="btn btn-success install-update-btn" data-version="<?=htmlspecialchars($p['version'],ENT_QUOTES)?>" data-signed="<?=!empty($p['signed'])?'1':'0'?>">⬆️ نصب بروزرسانی</button></form><?php endif;?><form method="post" style="display:inline"><input type="hidden" name="action" value="delete"><input type="hidden" name="file" value="<?=htmlspecialchars($p['file'])?>"><button class="btn btn-danger btn-sm">حذف</button></form></td></tr><?php endforeach;?></table></div></div><div class="card"><h2>تاریخچه عملیات</h2><table class="app-table"><tr><th>زمان</th><th>نسخه</th><th>منبع</th><th>امضا</th><th>تغییر/جدید/حفظ</th><th>وضعیت</th><th>خطا</th></tr><?php foreach($jobs as$j):?><tr><td><?=date('Y/m/d H:i',(int)$j['created_at'])?></td><td><?=htmlspecialchars($j['version'])?></td><td><?=$j['source']?></td><td><?=$j['signed_package']?'✅':'⚠️'?></td><td><?=$j['changed_files']?> / <?=$j['added_files']?> / <?=$j['skipped_files']?></td><td><?=$j['status']?></td><td><?=!empty($j['error_message'])?'جزئیات در گزارش امن سرور ثبت شده است.':''?></td></tr><?php endforeach;?></table></div></div></section></section><script>
(function(){
 const overlay=document.getElementById('updateProgress'), choice=document.getElementById('backupChoice'), bar=document.getElementById('progressBar'), pct=document.getElementById('progressPercent'), stage=document.getElementById('progressStage'), files=document.getElementById('progressFiles'), result=document.getElementById('progressResult'), title=document.getElementById('progressTitle');
 const createBtn=document.getElementById('createBackupBtn'), cancelBtn=document.getElementById('cancelUpdateBtn');
 let pendingForm=null;
 function paint(j){if(!j||!j.ok)return;const x=j.job||{},p=Math.max(0,Math.min(100,parseInt(x.progress_percent||0)));bar.style.width=p+'%';pct.textContent=p+'٪';stage.textContent=x.progress_stage||'در حال پردازش...';files.textContent=(x.processed_files||0)+' / '+(x.total_action_files||0)+' فایل';if(x.status==='failed'){result.className='progress-result fail';result.textContent=x.error_message||'بروزرسانی ناموفق بود';title.textContent='بروزرسانی متوقف شد';}if(x.status==='completed'){result.className='progress-result ok';result.textContent='نسخه جدید با موفقیت نصب و Runtime بازنشانی شد؛ صفحه در حال بارگذاری نسخه جدید است.';title.textContent='بروزرسانی تکمیل شد';}}
 async function startInstall(form,backupChoice){
   choice.classList.remove('show');pendingForm=null;
   form.querySelector('[name=backup_choice]').value=backupChoice;
   overlay.classList.add('show');result.className='progress-result';bar.style.width='1%';pct.textContent='1٪';title.textContent='آماده‌سازی بروزرسانی';
   stage.textContent='در حال آماده‌سازی بکاپ اجباری دیتابیس...';
   const job=form.querySelector('[name=job_id]').value;let done=false;
   const poll=setInterval(async()=>{try{const r=await fetch('update.php?ajax=progress&job_id='+encodeURIComponent(job),{credentials:'same-origin',cache:'no-store'});if(r.ok){const j=await r.json();paint(j);if(j.job&&(j.job.status==='completed'||j.job.status==='failed')){done=true;clearInterval(poll);if(j.job.status==='completed')setTimeout(()=>location.href='update.php',2200);}}}catch(e){}},700);
   try{const response=await fetch('update.php',{method:'POST',body:new FormData(form),credentials:'same-origin'});let data;try{data=await response.json();}catch(parseError){throw new Error('پاسخ سرور معتبر نبود؛ لاگ خطای PHP را بررسی کنید.');}if(!response.ok||!data.ok)throw new Error(data.error||'خطای ناشناخته');if(!done){bar.style.width='100%';pct.textContent='100٪';stage.textContent='پاک‌سازی و بارگذاری مجدد';result.className='progress-result ok';result.textContent=data.message||'بروزرسانی تکمیل شد';clearInterval(poll);setTimeout(()=>location.href='update.php',1800);}}
   catch(e){clearInterval(poll);title.textContent='بروزرسانی ناموفق';result.className='progress-result fail';result.textContent=e.message;stage.textContent='فایل‌ها در صورت امکان به نسخه قبل بازگردانده شدند.';}
 }
 document.querySelectorAll('.install-form').forEach(function(form){form.addEventListener('submit',function(ev){ev.preventDefault();pendingForm=form;const btn=form.querySelector('.install-update-btn'),version=btn?btn.dataset.version:'';choice.querySelector('h2').textContent='پیش از نصب نسخه «'+version+'»، بکاپ گرفته شود؟';choice.classList.add('show');});});
 createBtn.addEventListener('click',()=>{if(pendingForm)startInstall(pendingForm,'create');});
 cancelBtn.addEventListener('click',()=>{choice.classList.remove('show');pendingForm=null;});
})();
</script></body></html>
